import { click, settled } from "@ember/test-helpers";
import { module, test } from "qunit";
import { setupRenderingTest } from "discourse/tests/helpers/component-test";
import {
  setupRichEditor,
  testMarkdown,
} from "discourse/tests/helpers/rich-editor-helper";

module(
  "Integration | Component | prosemirror-editor - details extension",
  function (hooks) {
    setupRenderingTest(hooks);

    const aiBadge =
      '<span class="ai-badge" data-ai-label="AI" title="This content has been partially or fully generated by AI" contenteditable="false"></span>';

    const testCases = {
      details: [
        [
          `[details="Summary"]This text will be hidden[/details]`,
          `<details open="true"><summary>Summary</summary><p>This text will be hidden</p></details>`,
          `[details="Summary"]\nThis text will be hidden\n\n[/details]\n\n`,
        ],
      ],
      "details with open attribute": [
        [
          `[details="Summary" open]This text will be hidden[/details]`,
          `<details open="true"><summary>Summary</summary><p>This text will be hidden</p></details>`,
          `[details="Summary"]\nThis text will be hidden\n\n[/details]\n\n`,
        ],
      ],
      "details without summary": [
        [
          `[details]This text will be hidden[/details]`,
          `<details open="true"><summary></summary><p>This text will be hidden</p></details>`,
          `[details]\nThis text will be hidden\n\n[/details]\n\n`,
        ],
      ],
      "details without summary but with open attribute": [
        [
          `[details open]This text will be hidden[/details]`,
          `<details open="true"><summary></summary><p>This text will be hidden</p></details>`,
          `[details]\nThis text will be hidden\n\n[/details]\n\n`,
        ],
      ],
      "details with an AI marker": [
        [
          `[details="Summary" ai=true]Hidden text[/details]`,
          `<details open="true" class="ai-quote"><summary><span>Summary</span>${aiBadge}</summary><p>Hidden text</p></details>`,
          `[details="Summary" ai=true]\nHidden text\n\n[/details]\n\n`,
        ],
      ],
      "details with an AI marker and no summary": [
        [
          `[details ai=true]Hidden text[/details]`,
          `<details open="true" class="ai-quote"><summary><span></span>${aiBadge}</summary><p>Hidden text</p></details>`,
          `[details ai=true]\nHidden text\n\n[/details]\n\n`,
        ],
      ],
    };

    Object.entries(testCases).forEach(([name, tests]) => {
      tests.forEach(([markdown, expectedHtml, expectedMarkdown]) => {
        test(name, async function (assert) {
          await testMarkdown(assert, markdown, expectedHtml, expectedMarkdown, {
            multiToggle: true,
          });
        });
      });
    });

    test("pasting marked details preserves the marker and summary", async function (assert) {
      const [editor] = await setupRichEditor(assert, "");

      editor.view.pasteHTML(
        '<details class="ai-quote"><summary><span>Summary</span><span class="ai-details-label">AI</span></summary><p>Hidden text</p></details>'
      );
      await settled();

      assert
        .dom(".ProseMirror details summary")
        .hasText("Summary", "the rendered badge stays out of the summary");
      assert.strictEqual(
        editor.value,
        '[details="Summary" ai=true]\nHidden text\n\n[/details]\n\n',
        "the pasted label is serialized as an AI marker"
      );
    });

    test("editing a marked summary keeps its badge outside the editable text", async function (assert) {
      const [editor] = await setupRichEditor(
        assert,
        '[details="Summary" ai=true]Hidden text[/details]'
      );

      editor.view.dispatch(editor.view.state.tr.insertText("Edited ", 2));
      await settled();

      assert
        .dom(".ProseMirror details summary > span:first-child")
        .hasText("Edited Summary", "the summary updates in its own element");
      assert
        .dom(".ProseMirror details summary > .ai-badge")
        .exists("the badge remains next to the summary");
      assert.strictEqual(
        editor.value,
        '[details="Edited Summary" ai=true]\nHidden text\n\n[/details]\n\n',
        "the badge stays out of the serialized summary"
      );
    });

    test("opens and closes details on click", async function (assert) {
      const detailsMarkdown = `[details="Summary" ai=true]\nThis text will be hidden\n\n[/details]\n\n`;
      const [editor] = await setupRichEditor(assert, detailsMarkdown);

      const detailsCss = ".d-editor-input details";
      const summaryCss = `${detailsCss} summary`;
      assert.dom(detailsCss).hasAttribute("open");

      await click(summaryCss);
      assert.dom(detailsCss).doesNotHaveAttribute("open");
      assert.strictEqual(
        editor.value,
        detailsMarkdown,
        "closing keeps the AI marker"
      );

      // click elsewhere first to avoid a double-click being detected
      await click(`${detailsCss} p`);
      await click(summaryCss);

      assert.dom(detailsCss).hasAttribute("open");
    });
  }
);
